      {
        "id": "step3",
        "stepType": "SMS",
        "inputs": {
          "subAccountId": "8x8_subaccount_id",
          "destination": "{{data.payload.user.msisdn}}",
          "source": "sender_id",
          "text": "Hello, world!"
        },
        "nextStepId": "step4"
      },
      {
        "id": "step4",
        "stepType": "HttpRequest",
        "inputs": {
          "url": "https://example.com",
          "method": "POST",
          "headers": {
            "Authorization": "Bearer your_bearer_token"
          },
          "parameters": {
            "query_param_1": "query_param_value"
          },
          "body": {
            "data": {
              "field_1": "value_1",
              "field_2": {
                "field_3": "value_3"
              }
            }
          }
        },
